  "settings.compressionInfo": "Com restic empaqueta les dades noves en aquest repositori. Automàtic és l'opció per defecte de restic i va bé per a la majoria de dades. Màxim estalvia més espai i costa més temps de CPU durant les còpies. Desactivat desa les dades sense comprimir, cosa útil quan ja estan comprimides, com vídeo o fotos. Un repositori amb l'antic format de versió 1 no pot comprimir i ignora aquest ajust.",
