  "rcloneRemote.heading": "Afegeix una destinació SMB o WebDAV",
  "rcloneRemote.hint": "Arriba a una compartició de Windows o Samba, o a un servidor WebDAV com Nextcloud, sense haver de muntar res a l'amfitrió. restic desaconsella tenir un repositori en una compartició CIFS muntada, i aquesta via evita el muntatge del tot. La contrasenya es passa a rclone, que la desa en el seu propi format, i mai no es guarda en clar. NFS no s'ofereix aquí perquè ni restic ni rclone el suporten: per a NFS, munta l'exportació a Unraid i apunta un camí de còpia cap a ella.",
