  "dbdump.saveToFolder": "Desa en una carpeta",
  "dbdump.saveHint": "Escriu el bolcat com a fitxer a la carpeta triada del servidor, amb nobody:users com a propietari perquè el puguis obrir des del recurs compartit de xarxa. El fitxer conté totes les taules i els hash de contrasenya dels usuaris de la base de dades; desa'l on només hi arribis tu.",
  "dbdump.saveCancelHint": "Cancel·lar atura el desament i elimina el fitxer inacabat.",
  "dbdump.savedTo": "Desat a {path}",
  "dbdump.import": "Importa en una base de dades nova",
  "dbdump.importConfirm": "Vols importar aquest bolcat de {engine} {version} a {container}? BombVault atura el contenidor, aparta la seva carpeta de dades (es conserva, no s'esborra res), engega el contenidor amb una carpeta de dades buida i importa el bolcat. Les aplicacions que fan servir aquesta base de dades en veuran l'estat del moment del bolcat.",
  "dbdump.importConfirmNoVersion": "Vols importar aquest bolcat de {engine} a {container}? BombVault atura el contenidor, aparta la seva carpeta de dades (es conserva, no s'esborra res), engega el contenidor amb una carpeta de dades buida i importa el bolcat. Les aplicacions que fan servir aquesta base de dades en veuran l'estat del moment del bolcat.",
  "dbdump.importNoVersion": "Aquest bolcat no registra la versió de la seva base de dades. La importació falla si el servidor no la pot llegir.",
  "dbdump.importStops": "one=Mentre importa, BombVault també atura {apps} i després la torna a iniciar. Si la importació falla un cop començada, les dades antigues queden a part i l'aplicació aturada.|many=Mentre importa, BombVault també atura aquestes aplicacions: {apps}. Després les torna a iniciar. Si la importació falla un cop començada, les dades antigues queden a part i les aplicacions aturades.|other=Mentre importa, BombVault també atura aquestes aplicacions: {apps}. Després les torna a iniciar. Si la importació falla un cop començada, les dades antigues queden a part i les aplicacions aturades.",
  "dbdump.importDone": "Base de dades importada.",
  "dbdump.importRefused.busy": "Hi ha una altra còpia o restauració en marxa. Torna-ho a provar quan hagi acabat.",
  "dbdump.importRefused.notRunning": "Engega primer el contenidor; la importació necessita el servidor en marxa.",
  "dbdump.importRefused.engineMismatch": "Aquest bolcat ve d'un tipus de base de dades diferent del que fa servir el contenidor.",
  "dbdump.importRefused.noDataMount": "BombVault no arriba a la carpeta de dades d'aquest contenidor i no la pot apartar amb seguretat. Importa el bolcat a mà tal com descriu el kit de recuperació.",
  "dbdump.importRefused.version": "El servidor funciona amb la versió {server} i el bolcat ve de {dump}. Fes servir una imatge amb la versió {dump} o més nova per a aquesta importació.",
  "dbdump.importRefused.versionSameMajor": "El servidor funciona amb la versió {server} i el bolcat ve de {dump}. MySQL i MariaDB només importen un bolcat a la versió principal d'on prové, així que fes servir una imatge amb la versió {dump} per a aquesta importació.",
  "dbdump.importRefused.damaged": "Aquest bolcat està malmès i no es pot importar.",
  "dbdump.importRefused.notADump": "Aquesta instantània no és un bolcat de la base de dades d'aquest contenidor.",
  "dbdump.deleteConfirm": "Vols esborrar aquest bolcat de la base de dades? S'elimina del repositori (executa Prune a Configuració per recuperar l'espai). Això no es pot desfer.",
