  "auth.resetCodeTip": "BombVault ha escrit un codi al registre del seu contenidor. A Unraid: pestanya Docker, icona de BombVault, Logs. Un codi és vàlid durant 10 minuts. Qualsevol que pugui llegir aquest registre pot restablir la contrasenya, també amb un visor de registres com Dozzle. El restabliment també desactiva l'autenticació de doble factor, elimina totes les claus d'accés, revoca tots els testimonis de l'API i les claus MCP, tanca totes les altres sessions i impedeix que els telèfons s'aparellin fins que ho tornis a activar.",
