  // Scheduled flash zip export
  "flash.zipExport.title": "Exportació zip del Flash",
  "flash.zipExport.hint": "Després de cada còpia de Flash, escriu també la còpia com a .zip simple a una carpeta, llest per sincronitzar fora del servidor (Syncthing, rclone, una unitat al núvol).",
  "flash.zipExport.enable": "Exporta un zip després de cada còpia de Flash",
  "flash.zipExport.enableHint": "Cada cop que una còpia de Flash tingui èxit, la còpia s'escriu com a .zip a la carpeta de sota.",
  "flash.zipExport.path": "Carpeta d'exportació",
  "flash.zipExport.pathHint": "Subcamí relatiu sota l'arrel de muntatge de l'amfitrió on cau el .zip. Apunta'l a una carpeta de Syncthing/rclone per treure el Flash del servidor automàticament.",
  "flash.zipExport.keepHistory": "Conserva els fitxers zip exportats",
  "flash.zipExport.keepHistoryHint": "Desactivat: conserva un únic flash-latest.zip que se sobreescriu cada cop. Activat: conserva els N fitxers flash-<data>.zip amb marca de temps més recents. Això és independent de la retenció de restic: desactivat conserva un únic fitxer sempre sobreescrit (mai omple el destí); activat conserva els N més recents i elimina els antics.",
  "flash.zipExport.keepN": "Zips a conservar",
  "flash.zipExport.keepNHint": "Es conserven els N zips amb marca de temps més recents; els antics s'eliminen automàticament.",
  "flash.zipExport.latestNote": "Un únic flash-latest.zip se sobreescriu després de cada còpia.",
  "flash.zipExport.plaintextWarn": "El .zip exportat no està xifrat, encara que el teu repositori de Flash ho estigui. Sincronitza'l només en un lloc de confiança.",
  "flash.zipExport.pathRequired": "Tria una carpeta d'exportació per activar això.",
  "export.encrypt.hint": "Els repositoris restic ja estan xifrats. Això, opcionalment, segella els artefactes d'exportació simples (tar.gz de contenidor i MV més els seus companys xml, i el zip de Flash) amb age, perquè siguin segurs d'emmagatzemar o moure fora de la caixa.",
  "export.encrypt.ageInfo": "age (age-encryption.org) és una eina de xifratge de fitxers petita i moderna, una alternativa més senzilla a GPG per segellar un fitxer per a un o més destinataris.",
  "export.encrypt.enable": "Xifra les exportacions amb age",
  "export.encrypt.enableHint": "Quan està activat, les exportacions de contenidor, MV i Flash es segellen amb age abans d'escriure's al disc i obtenen el sufix .age.",
  "export.encrypt.kitSealed": "El kit de recuperació també se segella i arriba com a bombvault-recovery-kit.md.age. Continua sent text llegible (armadura ASCII), de manera que encara es pot enganxar en un gestor de contrasenyes o imprimir, però et caldrà la teva clau privada age per obrir-lo: guarda aquesta clau en un lloc que no depengui del mateix kit.",
  "export.encrypt.recipients": "Destinataris d'age",
  "export.encrypt.recipientsHint": "Un destinatari per línia. Fes servir una clau pública age (age1...) o una clau pública SSH. Per desxifrar fora de la caixa cal la clau privada corresponent. Amb el xifratge actiu i sense destinatari vàlid, l'exportació falla en comptes d'escriure text pla.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Afegeix almenys un destinatari d'age, altrament l'exportació xifrada fallarà.",

