  "recovery.abTitle": "Importa des del connector Appdata.Backup",
  "recovery.abIntro": "Converteix els arxius que va escriure el connector Appdata.Backup en punts de restauració dels contenidors corresponents, cadascun amb la data en què el connector el va crear. Els arxius només es llegeixen, mai no es modifiquen ni s'esborren. Cadascun es descomprimeix al costat del repositori, se'n fa còpia i la còpia descomprimida s'esborra de nou, així que allà cal espai per a l'arxiu més gran.",
