  "mcp.oauthToggle": "Inici de sessió amb OAuth",
  "mcp.oauthHint": "Per a ChatGPT, Claude a claude.ai i altres serveis que no accepten una clau. T'envien a una pàgina del BombVault on inicies sessió amb la teva contrasenya d'accés i els dones permís. Criden el BombVault des dels seus propis servidors, així que el BombVault ha de ser accessible des d'Internet a l'adreça pública de sota, amb un certificat en què confiïn els navegadors. Si el desactives, es tanca la sessió de tots els clients.",
