  "mcp.setupChatGPT": "A ChatGPT, obre Configuració, Aplicacions i connectors i activa el mode de desenvolupador a Configuració avançada. Després tria Crea, posa un nom al connector, enganxa l'URL del connector com a URL del servidor MCP, tria OAuth com a autenticació, confirma que hi confies i crea'l.",
