  "anomaly.acknowledgeHint": "Marca aquesta anomalia com a vista i la tanca. Mentre la causa hi sigui no se'n torna a informar; quan la causa hagi desaparegut i torni, sí. Si aquesta anomalia reté còpies antigues, es tornaran a esborrar a partir de la propera neteja. Si el canvi era volgut, és millor marcar-la com a esperada.",
  "anomaly.expectedHint": "Diu a BombVault que el canvi era volgut. Una mida o una durada noves passen a ser el nivell normal després de 10 còpies més, mentre que la comprovació d'una font gairebé buida continua activa. Per a les dades noves, les quantitats fins a aquesta ja no s'informen per a aquest element. Si aquesta anomalia reté còpies antigues, es tornaran a esborrar a partir de la propera neteja.",
