  "anomaly.sentence.newDataRenamed": "Tots els fitxers de {name} semblen nous tot i que hi ha una còpia anterior, i s'han tornat a desar {bytes} de {source}. Els fitxers reanomenats i reescrits alhora són típics del programari de segrest. Comprova els fitxers abans que res.",
  "anomaly.sentence.newDataFull": "BombVault ha tornat a llegir tots els fitxers de {name} perquè cap còpia anterior no coincidia (un repositori nou, carpetes noves o un xifratge canviat). Dades noves desades: {bytes}.",
