  "anomaly.settings.title": "Anomalies",
  "anomaly.settings.hint": "Compara cada còpia d'un element amb el seu propi historial i informa del que no encaixa. S'executa en segon pla després de cada còpia i no en frena cap. La majoria de comprovacions comencen després de 10 còpies d'un element; els errors, la reescriptura de la major part de les dades i una font gairebé buida es comproven des del principi. L'espai lliure es vigila als repositoris locals i als repositoris rclone que l'informen; a la compartició d'usuari d'Unraid és l'espai lliure de tota la matriu.",
  "anomaly.settings.toggle": "Detecta anomalies",
  "anomaly.settings.sensitivity": "Sensibilitat",
  "anomaly.settings.sensitivityHint": "Estricta informa de canvis més petits, Permissiva només dels grans, Equilibrada va bé per a la majoria de servidors. Cada element pot tenir la seva pròpia opció a Anomalies, Supervisió.",
  "anomaly.settings.notifyMin": "Envia una notificació per a",
  "anomaly.settings.notifyHint": "Fa servir els canals configurats a Notificacions. Cada element ho pot canviar a Anomalies, Supervisió. Els errors repetits de còpies i bolcats i les comprovacions de restauració programades fallides ja envien el seu propi missatge, així que no s'envien una segona vegada.",
  "anomaly.settings.notifyMuted": "Ara mateix no s'envia res: les notificacions estan desactivades o no hi ha cap canal configurat.",
  "anomaly.settings.openNotifications": "Obre la configuració de notificacions",
  "anomaly.settings.holdToggle": "Conserva les còpies antigues quan una font s'encongeix molt o es reescriu",
  "anomaly.settings.holdHint": "Tres troballes aturen l'esborrat de còpies antigues: una font que de sobte és gairebé buida, una que s'ha fet molt més petita i una còpia que ha tornat a desar la major part de les dades, que és l'aspecte d'un ransomware. La retenció esborraria les bones còpies antigues d'una en una. Mentre una anomalia així estigui oberta, es conserven les còpies antigues només d'aquell element (o d'aquell bolcat de base de dades o conjunt de dades ZFS); tota la resta es neteja com sempre. Confirma l'anomalia o marca-la com a esperada per reprendre-ho.",
