  "storage.flow.title": "Destinacions per secció",
  "storage.flow.hint": "El valor per defecte de cada secció. Al gràfic cada línia és un interruptor: fes clic en una línia o en un punt per activar-la o desactivar-la. Les línies discontínues estan desactivades. A «Interruptors» ho ajustes igual amb botons. Un interruptor decideix on van les còpies noves. Els elements que segueixen el valor per defecte s'hi mouen a l'instant, així que la còpia següent va a les destinacions noves. Les còpies ja desades es queden on són i encara les pots restaurar des d'allà. Els elements que han triat destinacions pròpies a la seva pàgina les conserven. Les regles pròpies d'una secció, com ara la conservació, la compressió o una adreça pròpia, s'ajusten a la pàgina de la destinació.",
