  "whatsNew.restoreTiles": "«Restauració» és una sola pàgina per a tot. Tria una secció o cerca un element, i després tria una còpia de seguretat a la seva cronologia.",
  "whatsNew.restoreWhere": "Una finestra pregunta què es restaura i on. «Al costat de l'original» recupera una còpia i deixa l'original com està.",
  "whatsNew.restoreMany": "Tria diversos elements amb Ctrl+clic, Maj+clic o una pulsació llarga i restaura'ls junts, un darrere l'altre.",
  "whatsNew.restoreEmergency": "Aquí comença l'assistent d'emergència. Recupera un servidor que ja no hi és o s'ha tornat a configurar, en quatre passos.",
  "whatsNew.anomaliesTiles": "Les rajoles trien la gravetat. «Oberta» o «Tancada» tria la llista.",
  "whatsNew.anomaliesRings": "Un anell per element mostra fins on la detecció ha après què és normal.",
  "whatsNew.storageList": "Les destinacions locals i externes són en una sola llista. Cada destinació té la seva pàgina.",
  "whatsNew.storageFlow": "El 3-2-1 en una imatge. Cada línia d'una secció a una destinació és un interruptor, també la Local, i un clic l'activa o la desactiva. Cada secció mostra quants dels seus elements fan la còpia en un altre lloc.",
  "whatsNew.locationKeep": "La retenció és «Curt», «Equilibrat», «Llarg» o valors propis. La cronologia mostra quines còpies de seguretat conserva una regla.",
  "whatsNew.locationMove": "«Mou» porta la còpia d'una secció a una altra destinació, amb tot l'historial.",
  "whatsNew.instancesPair": "Les instàncies s'aparellen amb dotze paraules. Després cadascuna mostra els seus rols com a rajoles.",
